import { MutableRefObject, RefObject, useEffect, useRef } from 'react';

import OpenFin from '@openfin/core';

import { createLogger } from '@common/utils/logger';

import { createAsyncSubscription } from './useAsyncSubscription';

const logger = createLogger('useForceSyncWindowHeight');

const HEIGHT_TOLERANCE_PX = 2;

const useCurrentWindowShown = createAsyncSubscription(
    'useForceSyncWindowHeight-shown',
    (cb: () => void) => (fin.me as OpenFin.Window).addListener('shown', cb),
    (cb: () => void) => (fin.me as OpenFin.Window).removeListener('shown', cb)
);

const setModalHeight = async (containerRef: RefObject<HTMLElement>, lastHeightRef: MutableRefObject<number>) => {
    if (!containerRef.current) {
        logger.warn('setModalHeight', 'containerRef.current is null, cannot set modal height');
        return;
    }

    try {
        const height = containerRef.current.offsetHeight;

        if (Math.abs(height - lastHeightRef.current) < HEIGHT_TOLERANCE_PX) {
            return;
        }

        lastHeightRef.current = height;
        logger.debug('setModalHeight', `Setting modal height to ${height}px`);
        await (fin.me as OpenFin.Window).setBounds({
            height: height
        });
    } catch (error) {
        logger.error('setModalHeight', 'Failed to set modal height', { error });
    }
};
/**
 * Custom hook to force-sync the OpenFin window height to match the container element height.
 * Observes resize changes and window shown events to keep the window height in sync.
 * Includes a tolerance guard to prevent feedback loops caused by DPI scaling mismatches
 * when moving windows between monitors with different scale factors.
 *
 * @param containerRef - Reference to the container element to observe
 */
export const useForceSyncWindowHeight = (containerRef: RefObject<HTMLElement>) => {
    const lastHeightRef = useRef(0);

    // Would be preferable to use 'visibilitychanged' but it is not firing reliably (backgroundThrottling? opacity vs hidden?)
    useCurrentWindowShown(() => {
        logger.debug('useForceSyncWindowHeight', 'Window shown event received, setting modal height');
        lastHeightRef.current = 0;
        setModalHeight(containerRef, lastHeightRef);
    });

    useEffect(() => {
        if (!containerRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            logger.debug('resizeObserver', 'Modal container resized, setting modal height');
            setModalHeight(containerRef, lastHeightRef);
        });

        resizeObserver.observe(containerRef.current);

        setModalHeight(containerRef, lastHeightRef);

        return () => {
            resizeObserver.disconnect();
        };
    }, [containerRef]);
};
